(()=>{const form=document.querySelector('#contact-request'),ready=document.querySelector('#email-ready'),link=document.querySelector('#prepared-email');if(!form||!ready||!link)return;form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const body=['Nome e cognome: '+data.get('name'),'Telefono: '+(data.get('phone')||'Non indicato'),'Email: '+data.get('email'),'','Richiesta:',data.get('message')].join(String.fromCharCode(10));link.href='mailto:clementipaolo@libero.it?subject='+encodeURIComponent('Richiesta dal sito Bianca Medical')+'&body='+encodeURIComponent(body);ready.hidden=false;});form.addEventListener('input',()=>{ready.hidden=true;link.removeAttribute('href');});})();
